/**
 * Messages, cut 6 (email in): the job an email's subject names. A job's number as the app shows it (a bid's
 * `BP523`, a GC project's `#42`, a Pipeline job's `JP1077`), standing alone in the subject, names that job; one the
 * sender is on wins over one they are not. With no number, a job's whole name in the subject names it, among the
 * sender's own jobs only. Two jobs named the same way name none. The reader then ties the line there; with none it
 * takes the person's star, and with no star it sits on the person (`email-in-mockups.html`, screen 1).
 */

export interface SubjectJob {
  /** `bid:<id>`, `project:<id>` or `pipeline:<id>` (`messages/load.ts`'s `jobKey`). */
  key: string
  /** The job's numbers as the app shows them. */
  labels: readonly string[]
  name: string
  /** The sender is on it: tied by the office, or by the facts. */
  mine: boolean
}

/** A number shorter than this names nothing: "#4" is in too many subjects. */
const LABEL_MIN = 3
/** A name shorter than this names nothing: "Shell" is in too many subjects. */
const NAME_MIN = 8

const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

/** The text stands alone in the subject: no letter or digit runs into either end of it. */
const standsAlone = (subject: string, text: string): boolean =>
  new RegExp(`(?:^|[^A-Za-z0-9])${escape(text)}(?![A-Za-z0-9])`, 'i').test(subject)

const onlyOne = (jobs: readonly SubjectJob[]): string | null => {
  const keys = [...new Set(jobs.map((j) => j.key))]
  return keys.length === 1 ? keys[0]! : null
}

/** The key of the job the subject names, or null. */
export function jobInSubject(subject: string, jobs: readonly SubjectJob[]): string | null {
  const s = subject.trim()
  if (!s) return null
  const byNumber = jobs.filter((j) => j.labels.some((l) => l.trim().length >= LABEL_MIN && standsAlone(s, l.trim())))
  if (byNumber.length > 0) {
    const mine = byNumber.filter((j) => j.mine)
    return onlyOne(mine.length > 0 ? mine : byNumber)
  }
  const byName = jobs.filter((j) => j.mine && j.name.trim().length >= NAME_MIN && standsAlone(s, j.name.trim()))
  return onlyOne(byName)
}
